-- Privacy-bounded administrative recovery review; never resets credentials or reveals account existence.
create table public.account_recovery_requests(id uuid primary key default gen_random_uuid(),email text not null,phone text not null,details text not null,status text not null default'pending'check(status in('pending','resolved','rejected')),reviewed_by uuid references public.profiles(id),review_note text,submitted_at timestamptz not null default now(),reviewed_at timestamptz,check(email=lower(email)),check(phone~'^01[3-9][0-9]{8}$'),check(char_length(details)between 10 and 1000),check((status='pending'and reviewed_at is null)or(status<>'pending'and reviewed_at is not null and reviewed_by is not null and char_length(review_note)between 10 and 1000)));
create unique index recovery_pending_email_idx on public.account_recovery_requests(email)where status='pending';alter table public.account_recovery_requests enable row level security;alter table public.account_recovery_requests force row level security;create policy recovery_super_read on public.account_recovery_requests for select to authenticated using(private.is_super_admin()and private.mfa_satisfied());revoke all on public.account_recovery_requests from anon,authenticated;grant select on public.account_recovery_requests to authenticated;create trigger recovery_prevent_delete before delete on public.account_recovery_requests for each row execute function private.prevent_receipt_mutation();
create or replace function public.submit_account_recovery_request(p_email text,p_phone text,p_details text,p_website text default null)returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$begin if coalesce(trim(p_website),'')<>''then return;end if;if lower(trim(p_email))!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'or p_phone!~'^01[3-9][0-9]{8}$'or char_length(trim(p_details))not between 10 and 1000 then raise exception'Invalid recovery request';end if;insert into public.account_recovery_requests(email,phone,details)values(lower(trim(p_email)),p_phone,trim(p_details))on conflict(email)where status='pending'do update set phone=excluded.phone,details=excluded.details,submitted_at=now();end;$$;
create or replace function public.review_account_recovery(p_request_id uuid,p_resolve boolean,p_note text)returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$declare item public.account_recovery_requests%rowtype;begin if not private.is_super_admin()or not private.mfa_satisfied()then raise exception'Super Admin AAL2 required';end if;if char_length(trim(p_note))not between 10 and 1000 then raise exception'Review note required';end if;select*into item from public.account_recovery_requests where id=p_request_id for update;if not found or item.status<>'pending'then raise exception'Pending recovery request not found';end if;update public.account_recovery_requests set status=case when p_resolve then'resolved'else'rejected'end,reviewed_by=auth.uid(),review_note=trim(p_note),reviewed_at=now()where id=item.id;perform private.write_audit_log(null,case when p_resolve then'account.recovery_resolved'else'account.recovery_rejected'end,'account_recovery',item.id,jsonb_build_object('request_id',item.id));end;$$;
revoke execute on function public.submit_account_recovery_request(text,text,text,text),public.review_account_recovery(uuid,boolean,text)from public;grant execute on function public.submit_account_recovery_request(text,text,text,text)to anon,authenticated;grant execute on function public.review_account_recovery(uuid,boolean,text)to authenticated;comment on table public.account_recovery_requests is'Administrative review requests that never disclose account existence and never directly mutate Auth credentials.';
